/**
 * PUBLIC_INTERFACE
 * Submits recruiter feedback to backend /analyze-feedback endpoint.
 * @param params { feedback: string }
 * @returns Promise<{ summary: string; suggestions: string[] }>
 */
export const analyzeFeedback = async ({
  feedback,
}: {
  feedback: string;
}): Promise<{ summary: string; suggestions: string[] }> => {
  const res = await fetch(`${BACKEND_API_BASE}/analyze-feedback`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
    },
    body: JSON.stringify({ feedback }),
  });

  if (!res.ok) {
    let detail = "";
    try {
      const err = await res.json();
      detail = err?.detail || "";
    } catch {
      detail = res.statusText;
    }
    throw new Error(
      `Failed to analyze feedback (${res.status}): ${detail || "Unknown error."}`
    );
  }
  return res.json();
};
